package dev.kuan.kuanperion.automation.pest;
import dev.kuan.kuanperion.automation.*;import java.nio.file.*;import java.util.*;
public final class PestSprayServiceTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static class F extends PestSprayTaskTest.Fixture implements PestSpraySelectionTask.Port {
  final AutomationSettingsStore settings;final PestSprayService service;boolean allowed=true,failDemand;int notices;
  F()throws Exception{settings=AutomationSettingsStore.load(Files.createTempDirectory("spray-service-").resolve("automation.json"));settings.setPestSprayPolicy(PestSprayPlanTest.policy(),PestSprayBuying.defaults());service=new PestSprayService(settings,session,coordinator,receipts,new CursorReceipts(),this,()->allowed,n->notices++);}
  @Override public void requestSprayData(AutomationSession.Handle h){super.requestSprayData(h);if(failDemand)throw new IllegalStateException("demand fault");}
  public PestSpraySelectionTask.Frame selectionFrame(long n){throw new AssertionError("already selected must not open GUI");}public PestSprayTask.Effect selectionEffect(AutomationSession.Handle h,PestSpraySelectionTask.Action a,long n){throw new AssertionError("already selected must not send selection");}
  @Override public PestSprayTask.Effect sprayEffect(AutomationSession.Handle h,PestSprayTask.Action a,long n){check(a.claim(h,sprayFrame(n),n),"real private native claim");switch(a.kind()){case EQUIP->{equips++;selected=4;}case RESTORE->{restores++;selected=0;}case USE->{uses++;inv=new HashMap<>(inv);inv.put(9,PestSprayPlanTest.material(9));receipts.observe(1,0,9,inv.get(9));service.onSystemMessage(1,"Sprayonator! You sprayed plot 1!",n);spray=new PestSprayObservation(PestSprayObservation.State.ACTIVE);applyTab();}}return PestSprayTask.Effect.SENT;}
  @Override void tick(){now+=200_000_000L;if(spray.state()==PestSprayObservation.State.NONE)applyTab();service.tick(now);}
 }
 public static void main(String[]args)throws Exception{
  var f=new F();f.tick();check(!f.service.autoEnabled()&&!f.service.active()&&f.pauses==0&&f.dataRequests==0,"independent default off, no startup network/effect");f.service.setEnabled(true);for(int i=0;i<20;i++)f.tick();check(f.uses==1&&f.restores==1&&f.pauses==1&&f.stops==0&&f.service.autoEnabled()&&!f.service.active(),"automatic source-cadence selected spray completes original hold");
  f=new F();f.allowed=false;check(f.service.manualRequest(f.now)&&f.service.pending()&&!f.service.active()&&f.pauses==0&&f.dataRequests==0,"own settings click is intent only");for(int i=0;i<5;i++)f.tick();check(f.pauses==0,"no effects while own settings remains open");f.allowed=true;for(int i=0;i<20;i++)f.tick();check(!f.service.pending()&&f.uses==1&&f.stops==0,"closing settings dispatches exactly one deferred original root");
  for(String mode:List.of("manual","Jerry","world","farm-stop","expiry","busy")){f=new F();f.allowed=false;check(f.service.manualRequest(f.now),"pending setup");switch(mode){case "manual"->f.service.cancel(f.now);case "Jerry"->f.service.suspend(f.now);case "world"->f.context=new AutomationContext(2,true,true,Set.of());case "farm-stop"->f.context=new AutomationContext(1,false,true,Set.of());case "expiry"->f.now+=30*PestSprayTaskTest.S;case "busy"->f.session.begin(AutomationFeature.BOOK_COMBINE,f.now,120*PestSprayTaskTest.S);}f.allowed=true;f.tick();check(!f.service.pending()&&!f.service.active()&&f.dataRequests==0,"pending intent revoked without replay: "+mode);}
  f=new F();f.service.setEnabled(true);var other=f.session.begin(AutomationFeature.VISITOR,f.now,120*PestSprayTaskTest.S);f.tick();check(f.session.isCurrent(other)&&f.dataRequests==0&&f.uses==0,"busy root cannot be observed/preempted by due timer");f.session.finish(other,true,f.now);f.tick();check(f.service.active()&&f.dataRequests==1,"due poll was not consumed by another root");f.manual=true;f.tick();check(!f.service.active()&&!f.service.autoEnabled()&&!f.settings.enabled(AutomationFeature.PEST_SPRAY)&&f.stops==1,"failed/manual run persists automatic disable, never retries");f.manual=false;for(int i=0;i<60;i++)f.tick();check(f.dataRequests==1,"no silent failure replay");
  f=new F();f.context=new AutomationContext(1,false,true,Set.of());check(!f.service.manualRequest(f.now)&&!f.service.pending(),"spray never arms Farming from idle manual intent");
  f=new F();f.failDemand=true;f.service.setEnabled(true);for(int i=0;i<25;i++)f.tick();check(!f.service.active()&&!f.service.autoEnabled()&&f.stops==1&&f.dataRequests==1,"failed startup after root acquisition must persist suspension, not silently replay every poll");
  System.out.println("PestSprayServiceTest: PASS original task/hold, defaults, cadence, intent and interruption models; not live acceptance");
 }
}
